const items = $input.all();
const results = [];

function parseJsonSafely(value, fallback = {}) {
  if (value === null || value === undefined || value === '') {
    return fallback;
  }

  if (typeof value === 'object') {
    return value;
  }

  if (typeof value !== 'string') {
    return fallback;
  }

  const cleaned = value.trim().replace(/^=/, '');

  if (!cleaned) {
    return fallback;
  }

  try {
    return JSON.parse(cleaned);
  } catch {
    return fallback;
  }
}

function unwrapInput(raw) {
  let value = raw;

  // Handle a JSON string, including n8n values beginning with "=".
  if (typeof value === 'string') {
    const parsed = parseJsonSafely(value, null);
    value = parsed ?? { githubRepo: value.trim().replace(/^=/, '') };
  }

  // Handle an API response supplied as a one-element array.
  if (Array.isArray(value)) {
    return value.length > 0 ? unwrapInput(value[0]) : {};
  }

  if (!value || typeof value !== 'object') {
    return {};
  }

  // Handle objects reconstructed as {"0":"{", "1":"\"", ...}.
  const numericKeys = Object.keys(value)
    .filter((key) => /^\d+$/.test(key))
    .sort((a, b) => Number(a) - Number(b));

  if (numericKeys.length > 0) {
    const reconstructed = numericKeys
      .map((key) => value[key])
      .join('')
      .trim()
      .replace(/^=/, '');

    const parsed = parseJsonSafely(reconstructed, null);
    return parsed ? unwrapInput(parsed) : { githubRepo: reconstructed };
  }

  // Common wrappers returned by HTTP/API nodes.
  if (Array.isArray(value.data)) {
    return value.data.length > 0 ? unwrapInput(value.data[0]) : {};
  }

  if (
    value.data &&
    typeof value.data === 'object' &&
    Object.keys(value).length === 1
  ) {
    return unwrapInput(value.data);
  }

  if (Array.isArray(value.body)) {
    return value.body.length > 0 ? unwrapInput(value.body[0]) : {};
  }

  return value;
}

function parseRepository(value) {
  const raw = String(value ?? '')
    .trim()
    .replace(/^=/, '')
    .replace(/^https?:\/\/github\.com\//i, '')
    .replace(/^git@github\.com:/i, '')
    .replace(/\.git$/i, '')
    .replace(/^\/+|\/+$/g, '');

  const parts = raw.split('/').filter(Boolean);

  return {
    owner: parts[0] ?? '',
    name: parts[1] ?? '',
  };
}

function cleanPath(value) {
  return String(value ?? '')
    .trim()
    .replace(/^\/+/, '')
    .replace(/\\/g, '/');
}

function selectTargetFile(explicitPath, filesTargeted, sonarIssues) {
  const explicit = cleanPath(explicitPath);

  if (explicit) {
    return explicit;
  }

  const declaredFiles = Array.isArray(filesTargeted)
    ? filesTargeted.map(cleanPath).filter(Boolean)
    : [];

  if (declaredFiles.length > 0) {
    return declaredFiles[0];
  }

  const severityWeight = {
    BLOCKER: 500,
    CRITICAL: 400,
    HIGH: 350,
    MAJOR: 300,
    MEDIUM: 200,
    MINOR: 100,
    LOW: 50,
    INFO: 10,
  };

  const typeWeight = {
    VULNERABILITY: 30,
    BUG: 20,
    SECURITY_HOTSPOT: 15,
    CODE_SMELL: 10,
  };

  const candidates = (Array.isArray(sonarIssues) ? sonarIssues : [])
    .map((issue, index) => ({
      issue,
      index,
      path: cleanPath(issue?.component),
      score:
        (severityWeight[String(issue?.severity ?? '').toUpperCase()] ?? 0) +
        (typeWeight[String(issue?.type ?? '').toUpperCase()] ?? 0),
    }))
    .filter((entry) => entry.path)
    .sort((a, b) => {
      if (b.score !== a.score) {
        return b.score - a.score;
      }
      return a.index - b.index;
    });

  return candidates[0]?.path ?? 'ci-cd/Jenkinsfile';
}

for (const item of items) {
  const itemJson = item.json ?? {};

  // Prefer incidentData when it is populated. Otherwise accept the whole item.
  const source =
    itemJson.incidentData !== null &&
    itemJson.incidentData !== undefined
      ? itemJson.incidentData
      : itemJson;

  const d = unwrapInput(source);
  const project = d.project && typeof d.project === 'object'
    ? d.project
    : {};

  const parsedAiAnalysis = parseJsonSafely(d.aiAnalysis, {});
  const aiAnalysis =
    parsedAiAnalysis &&
    typeof parsedAiAnalysis === 'object' &&
    !Array.isArray(parsedAiAnalysis)
      ? parsedAiAnalysis
      : {};

  const sonarIssues = Array.isArray(d.sonarIssues)
    ? d.sonarIssues
    : Array.isArray(d.metadata?.enrichedData?.sonar?.issues)
      ? d.metadata.enrichedData.sonar.issues
      : [];

  const filesTargeted = Array.isArray(d.files_targeted)
    ? d.files_targeted
    : [];

  const decision = String(
    d.decision ??
    aiAnalysis.decision ??
    ''
  ).trim().toUpperCase();

  const riskLevel = String(
    d.riskLevel ??
    aiAnalysis.securityLevel ??
    'low'
  ).trim().toLowerCase();

  const confidenceRaw = Number(
    d.confidenceScore ??
    aiAnalysis.confidenceScore ??
    1
  );

  const confidenceScore = Number.isFinite(confidenceRaw)
    ? (confidenceRaw > 1 ? confidenceRaw / 100 : confidenceRaw)
    : 0;

  const parsedRepo = parseRepository(
    d.githubRepo ??
    d.repository ??
    project.githubRepo ??
    ''
  );

  const repositoryOwner = String(
    d.repository_owner ??
    parsedRepo.owner
  ).trim();

  const repositoryName = String(
    d.repository_name ??
    parsedRepo.name
  ).trim().replace(/\.git$/i, '');

  const targetFilePath = selectTargetFile(
    d.target_file_path,
    filesTargeted,
    sonarIssues
  );

  const defaultBranch = String(
    d.branch ??
    d.default_branch ??
    project.defaultBranch ??
    'main'
  ).trim() || 'main';

  const incidentId = String(
    d.incidentId ??
    d.incidentUUID ??
    d.id ??
    ''
  ).trim();

  const projectId = String(
    d.projectId ??
    project.id ??
    ''
  ).trim();

  const blockReasons = [];
  let blocked = false;

  if (decision === 'BLOCK') {
    blocked = true;
    blockReasons.push('Judge decision is BLOCK');
  }

  if (confidenceScore < 0.5) {
    blocked = true;
    blockReasons.push(`Confidence too low: ${confidenceScore}`);
  }

  if (!repositoryOwner) {
    blocked = true;
    blockReasons.push('Missing repository_owner');
  }

  if (!repositoryName) {
    blocked = true;
    blockReasons.push('Missing repository_name');
  }

  if (!targetFilePath) {
    blocked = true;
    blockReasons.push('Missing target_file_path');
  }

  if (!incidentId) {
    blocked = true;
    blockReasons.push('Missing incidentId');
  }

  results.push({
    json: {
      ...d,

      // Normalized values consumed by all later WF2 nodes.
      incidentId,
      projectId,
      aiAnalysis,
      sonarIssues,
      files_targeted: filesTargeted,
      blocked,
      block_reason: blocked
        ? blockReasons.join('; ')
        : 'All constraints passed',
      repository_owner: repositoryOwner,
      repository_name: repositoryName,
      target_file_path: targetFilePath,
      default_branch: defaultBranch,
      confidenceScore,
      decision,
      riskLevel,

      backend_base_url: String(
        d.backendBaseUrl ??
        'http://172.31.172.61:3001'
      ).replace(/\/+$/, ''),
    },
  });
}

return results;

const current = $input.first().json;
const gate = $('Policy Gate - Validate Constraints').first().json;

const errorMessage = String(
  current.error?.message ??
  current.message ??
  current.errorDescription ??
  'GitHub file fetch failed'
);

return [{
