    blocked: true,
    retryable: false,
    step: 'fetch_repository_file',
    error_message: errorMessage.slice(0, 2000),
    http_status:
      current.error?.status ??
      current.statusCode ??
      current.httpCode ??
      null,
    incidentId: gate.incidentId || null,
    projectId: gate.projectId || null,
    repository_owner: gate.repository_owner || null,
