const input = $input.first().json;
const gate = $('Policy Gate - Validate Constraints').first().json;

if (!input.content) {
  throw new Error(
    `GitHub response does not contain file content for ${gate.target_file_path}`
  );
}

const fileContent = Buffer
  .from(String(input.content).replace(/\n/g, ''), 'base64')
  .toString('utf-8');

const fileName =
  input.path ||
  gate.target_file_path ||
  'ci-cd/Jenkinsfile';

const allIssues = Array.isArray(gate.sonarIssues)
  ? gate.sonarIssues
  : [];

const relevantIssues = allIssues.filter(
  (issue) => String(issue?.component ?? '') === fileName
);

const issueText = relevantIssues.length > 0
  ? relevantIssues.map((issue, index) => [
      `${index + 1}. Severity: ${issue.severity ?? 'UNKNOWN'}`,
      `   Type: ${issue.type ?? 'UNKNOWN'}`,
      `   Line: ${issue.line ?? 'unknown'}`,
      `   Message: ${issue.message ?? 'No message'}`,
    ].join('\n')).join('\n')
  : 'No file-specific SonarQube issue was supplied. Apply only the relevant remediation instructions below.';

const ai = gate.aiAnalysis || {};

const remediationText = [
  ai.developerActions
    ? `DEVELOPER ACTIONS:\n${ai.developerActions}`
    : '',
  ai.securityIssues
    ? `SECURITY ISSUES:\n${ai.securityIssues}`
    : '',
  ai.recommendations
    ? `RECOMMENDATIONS:\n${ai.recommendations}`
    : '',
].filter(Boolean).join('\n\n') ||
  gate.description ||
  'Apply secure coding best practices without changing unrelated behavior.';

const prompt = `You are an expert DevSecOps engineer.

Modify exactly one file: ${fileName}

CURRENT FILE:
<ORIGINAL_FILE>
${fileContent}
</ORIGINAL_FILE>

FILE-SPECIFIC ISSUES:
${issueText}

REMEDIATION CONTEXT:
${remediationText}

MANDATORY RULES:
- Return the COMPLETE corrected file, not a diff.
- Modify only ${fileName}.
- Apply only fixes relevant to this file.
- Preserve all valid existing behavior and pipeline logic.
- Do not invent unavailable classes, methods, secrets, paths, or dependencies.
- Never include markdown fences.
- The patched file must not be empty.
- Respond using exactly these three tags:

<PATCH_DESCRIPTION>brief description</PATCH_DESCRIPTION>
<COMMIT_MESSAGE>fix: concise commit message</COMMIT_MESSAGE>
<PATCHED_CODE>
complete corrected file content
</PATCHED_CODE>`;

const body = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 8192,
  messages: [
    {
      role: 'user',
      content: prompt,
    },
  ],
};

return [{
  json: {
    claudeBodyString: JSON.stringify(body),
    file_sha: input.sha || '',
    file_path: fileName,
    repository_owner: gate.repository_owner,
    repository_name: gate.repository_name,
    default_branch: gate.default_branch,
    incidentId: gate.incidentId || '',
    projectId: gate.projectId || '',
    backend_base_url: gate.backend_base_url,
  },
}];

const response = $input.first().json || {};
const prepare = $('Prepare - Code Patch Body').first().json || {};

const text = response.content
  ?.filter((part) => part.type === 'text')
  .map((part) => part.text)
  .join('\n')
  .trim() || '';

function extractTag(name) {
  const pattern = new RegExp(
    `<${name}>\\s*([\\s\\S]*?)\\s*</${name}>`,
    'i'
  );
  return text.match(pattern)?.[1]?.trim() || '';
}

const patchDescription = extractTag('PATCH_DESCRIPTION');
const commitMessage = extractTag('COMMIT_MESSAGE');
const patchedCode = extractTag('PATCHED_CODE');

const validPatch = Boolean(
  text &&
  patchedCode &&
  prepare.file_sha &&
  prepare.file_path &&
  prepare.repository_owner &&
  prepare.repository_name
);

const branchName =
  `fix/ai-devsecops-${Date.now()}`;

return [{
  json: {
    valid_patch: validPatch,
    parse_error: validPatch
      ? null
      : 'Claude response is missing PATCHED_CODE or required GitHub metadata',
    incidentId: prepare.incidentId || 'unknown',
    projectId: prepare.projectId || '',
    patchDescription:
      patchDescription ||
      'Automated DevSecOps security correction',
    commitMessage:
      commitMessage ||
      'fix: automated DevSecOps security patch',
    branchName,
    file_sha: prepare.file_sha || '',
    file_path: prepare.file_path || '',
    patchedCode,
    content_base64: patchedCode
      ? Buffer.from(patchedCode, 'utf8').toString('base64')
      : '',
    repository_owner: prepare.repository_owner || '',
    repository_name: prepare.repository_name || '',
    default_branch: prepare.default_branch || 'main',
    backend_base_url: prepare.backend_base_url,
  },
}];

const gate = $input.first().json;
return [{ json: {
  success: false,
  status: 'blocked',
  blocked: true,
  reason: gate.block_reason,
  repository_owner: gate.repository_owner || null,
  repository_name: gate.repository_name || null,
  target_file_path: gate.target_file_path || null,
  incidentId: gate.incidentId || null,
} }];

